Here is the commit message:
drm/msm/dpu: Add missing NULL pointer check for pingpong
 interface

It is checked almost always in dpu_encoder_phys_wb_setup_ctl(), but in a
single place the check is missing.
Also use convenient locals instead of phys_enc->* where available.

Cc: stable@vger.kernel.org
Fixes: d7d0e73f7de33 ("drm/msm/dpu: introduce the dpu_encoder_phys_* for writeback")
Signed-off-by: Nikolay Kuratov <kniv@yandex-team.ru>
Reviewed-by: Dmitry Baryshkov <dmitry.baryshkov@oss.qualcomm.com>
Patchwork: https://patchwork.freedesktop.org/patch/693860/
Link: https://lore.kernel.org/r/20251211093630.171014-1-kniv@yandex-team.ru
Signed-off-by: Dmitry Baryshkov <dmitry.baryshkov@oss.qualcomm.com>

Here is the root cause:
In `dpu_encoder_phys_wb_setup_ctl()`, the code accessed `phys_enc->hw_pp->merge_3d` without verifying that `phys_enc->hw_pp` is not NULL, while other parts of the same function properly check for NULL. This missing NULL pointer check can lead to a NULL pointer dereference when the pingpong block is not available.

Here is the patch:
  */
 static void dpu_encoder_phys_wb_setup_ctl(struct dpu_encoder_phys *phys_enc)
 {
 	struct dpu_hw_wb *hw_wb;
 	struct dpu_hw_cdm *hw_cdm;

 	if (!phys_enc) {
 		DPU_ERROR("invalid encoder\n");
 		return;
 	}

 	hw_wb = phys_enc->hw_wb;
 	hw_cdm = phys_enc->hw_cdm;

 	if (phys_enc->dpu_kms->catalog->mdss_ver->core_major_ver >= 5 &&
 		(phys_enc->hw_ctl &&
 		 phys_enc->hw_ctl->ops.setup_intf_cfg)) {
 		struct dpu_hw_intf_cfg intf_cfg = {0};
 		struct dpu_hw_pingpong *hw_pp = phys_enc->hw_pp;
 		enum dpu_3d_blend_mode mode_3d;

 		mode_3d = dpu_encoder_helper_get_3d_blend_mode(phys_enc);

 		intf_cfg.intf = DPU_NONE;
 		intf_cfg.wb = hw_wb->idx;
 		intf_cfg.cwb = dpu_encoder_helper_get_cwb_mask(phys_enc);

 		if (mode_3d && hw_pp && hw_pp->merge_3d)
 			intf_cfg.merge_3d = hw_pp->merge_3d->idx;

 		if (hw_cdm)
 			intf_cfg.cdm = hw_cdm->idx;

-		if (phys_enc->hw_pp->merge_3d && phys_enc->hw_pp->merge_3d->ops.setup_3d_mode)
-			phys_enc->hw_pp->merge_3d->ops.setup_3d_mode(phys_enc->hw_pp->merge_3d,
-					mode_3d);
+		if (hw_pp && hw_pp->merge_3d && hw_pp->merge_3d->ops.setup_3d_mode)
+			hw_pp->merge_3d->ops.setup_3d_mode(hw_pp->merge_3d, mode_3d);

 		/* setup which pp blk will connect to this wb */
-		if (hw_pp && phys_enc->hw_wb->ops.bind_pingpong_blk)
-			phys_enc->hw_wb->ops.bind_pingpong_blk(phys_enc->hw_wb,
-					phys_enc->hw_pp->idx);
+		if (hw_pp && hw_wb->ops.bind_pingpong_blk)
+			hw_wb->ops.bind_pingpong_blk(hw_wb, hw_pp->idx);

 		phys_enc->hw_ctl->ops.setup_intf_cfg(phys_enc->hw_ctl, &intf_cfg);
 	} else if (phys_enc->hw_ctl && phys_enc->hw_ctl->ops.setup_intf_cfg) {
 		struct dpu_hw_intf_cfg intf_cfg = {0};

 		intf_cfg.intf = DPU_NONE;
 		intf_cfg.wb = hw_wb->idx;
 		intf_cfg.mode_3d =
 			dpu_encoder_helper_get_3d_blend_mode(phys_enc);
 		phys_enc->hw_ctl->ops.setup_intf_cfg(phys_enc->hw_ctl, &intf_cfg);
 	}
 }



